custom_css:
/* 01-tokens.css */
:root {
    --ef-void: #111111;
    --ef-charcoal: #202727;
    --ef-panel: #2c6467;
    --ef-panel-deep: #183a3b;
    --ef-flow: #1dafaa;
    --ef-flow-mid: #5eb5a3;
    --ef-flow-soft: #a1e1d6;
    --ef-xirang: #71c997;
    --ef-paper: #e8eaea;
    --ef-worn: #7c7868;
    --ef-line: rgba(161, 225, 214, 0.24);
    --ef-line-quiet: rgba(161, 225, 214, 0.11);
    --ef-cut: 10px;
    --ef-feedback: 120ms;
    --ef-extend: 180ms;
}

body {
    --SmartThemeBodyColor: var(--ef-paper) !important;
    --SmartThemeEmColor: var(--ef-flow-soft) !important;
    --SmartThemeUnderlineColor: var(--ef-xirang) !important;
    --SmartThemeQuoteColor: var(--ef-flow-mid) !important;
    --SmartThemeBlurTintColor: rgba(17, 17, 17, 0.96) !important;
    --SmartThemeChatTintColor: rgba(17, 17, 17, 0.88) !important;
    --SmartThemeUserMesBlurTintColor: rgba(44, 100, 103, 0.22) !important;
    --SmartThemeBotMesBlurTintColor: rgba(17, 17, 17, 0.52) !important;
    --SmartThemeBorderColor: var(--ef-line) !important;
    --SmartThemeShadowColor: transparent !important;
}

/* 02-foundation.css */
#chat {
    background-color: rgba(17, 17, 17, 0.88) !important;
    background-image:
        linear-gradient(90deg, rgba(29, 175, 170, 0.075), transparent 28%),
        repeating-linear-gradient(
            90deg,
            transparent 0,
            transparent 47px,
            rgba(161, 225, 214, 0.025) 47px,
            rgba(161, 225, 214, 0.025) 48px
        ) !important;
    border-color: var(--ef-line) !important;
    box-shadow: none !important;
}

#chat a {
    color: var(--ef-flow-soft) !important;
    text-decoration-color: rgba(161, 225, 214, 0.42) !important;
    text-underline-offset: 0.16em;
}

#chat blockquote {
    border-left-color: var(--ef-flow-mid) !important;
    color: rgba(232, 234, 234, 0.86) !important;
}

/* 03-chat.css */
#chat .mes {
    position: relative;
    padding: 12px 14px 10px !important;
    border-bottom: 1px solid var(--ef-line-quiet) !important;
    background: rgba(17, 17, 17, 0.36) !important;
    box-shadow: none !important;
    transition:
        background-color var(--ef-feedback) ease-out,
        border-color var(--ef-feedback) ease-out;
}

#chat .mes[is_user="true"] {
    background: linear-gradient(90deg, rgba(44, 100, 103, 0.3), rgba(17, 17, 17, 0.3) 58%) !important;
}

#chat .mes::before {
    content: "";
    position: absolute;
    z-index: 1;
    top: 10px;
    bottom: 10px;
    left: 0;
    width: 3px;
    pointer-events: none;
    background: linear-gradient(180deg, var(--ef-flow-soft), var(--ef-flow), transparent 92%);
    clip-path: polygon(0 0, 100% 0, 100% 88%, 0 100%);
    opacity: 0.52;
    transform: scaleY(0.36);
    transform-origin: top;
    transition:
        transform var(--ef-extend) ease-out,
        opacity var(--ef-feedback) ease-out;
}

#chat .mes:hover,
#chat .mes:focus-within {
    background-color: rgba(44, 100, 103, 0.2) !important;
    border-bottom-color: var(--ef-line) !important;
}

#chat .mes:hover::before,
#chat .mes:focus-within::before {
    opacity: 0.92;
    transform: scaleY(1);
}

#chat .mes[is_user="true"]::before {
    background: linear-gradient(180deg, var(--ef-xirang), var(--ef-flow), transparent 92%);
}

#chat .ch_name .name_text {
    color: var(--ef-flow-soft) !important;
    letter-spacing: 0.035em;
}

#chat .mes[is_user="true"] .ch_name .name_text {
    color: var(--ef-xirang) !important;
}

/* 04-input.css */
#send_form {
    border: 1px solid var(--ef-line) !important;
    border-radius: 0 !important;
    background:
        linear-gradient(90deg, rgba(29, 175, 170, 0.1), transparent 38%),
        rgba(17, 17, 17, 0.96) !important;
    box-shadow: none !important;
    clip-path: polygon(
        0 0,
        calc(100% - var(--ef-cut)) 0,
        100% var(--ef-cut),
        100% 100%,
        var(--ef-cut) 100%,
        0 calc(100% - var(--ef-cut))
    );
    transition:
        border-color var(--ef-feedback) ease-out,
        background-color var(--ef-feedback) ease-out;
}

#send_form:focus-within {
    border-color: rgba(122, 227, 202, 0.78) !important;
    outline: 1px solid rgba(29, 175, 170, 0.36) !important;
    outline-offset: 2px;
}

#send_textarea {
    color: var(--ef-paper) !important;
    caret-color: var(--ef-flow-soft) !important;
}

#send_textarea::placeholder {
    color: rgba(232, 234, 234, 0.45) !important;
}

#send_but {
    color: var(--ef-flow-soft) !important;
    background: rgba(44, 100, 103, 0.26) !important;
    border-radius: 0 !important;
    clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 0 100%);
    transition:
        color var(--ef-feedback) ease-out,
        background-color var(--ef-feedback) ease-out;
}

#send_but:hover,
#send_but:focus-visible {
    color: var(--ef-paper) !important;
    background: rgba(29, 175, 170, 0.38) !important;
}

@media (max-width: 600px) {
    #chat .mes {
        padding: 10px 10px 8px !important;
    }

    #send_form {
        --ef-cut: 7px;
    }
}

/* 05-motion.css */
@media (prefers-reduced-motion: reduce) {
    #chat .mes,
    #chat .mes::before,
    #send_form,
    #send_but {
        transition: none !important;
    }

    #chat .mes::before {
        transform: scaleY(1) !important;
    }
}
